<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="theme-color" content="#f5f3ed">
    <meta name="description" content="Arcflow provides invoice, payment detection, and webhook infrastructure for USDC payments on Arc.">
    <title>Arcflow — Stablecoin payments, thoughtfully built</title>
    <style>
        :root{--paper:#f5f3ed;--surface:#fffefa;--ink:#202a2c;--muted:#687174;--line:#e4e3dc;--green:#08765f;--green-dark:#075746;--mint:#e4f1eb;--serif:Georgia,'Times New Roman',serif;--sans:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}
        *{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased}a{color:inherit;text-decoration:none}.shell{max-width:1240px;margin:auto;padding:0 34px}.nav{height:78px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(32,42,44,.1)}.brand{display:flex;align-items:center;gap:11px;font-family:var(--serif);font-size:25px;letter-spacing:-.06em;font-weight:700}.mark{width:30px;height:30px;display:grid;place-items:center;border:1.5px solid var(--green);color:var(--green);border-radius:9px;font-family:var(--sans);font-size:17px;font-weight:800;transform:rotate(-5deg)}.navlinks{display:flex;align-items:center;gap:30px;font-size:12px;color:#515c5e}.navlinks a:hover{color:var(--green)}.navactions{display:flex;align-items:center;gap:18px;font-size:12px}.button{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:13px 18px;border-radius:7px;font-size:12px;font-weight:650;border:1px solid var(--green);transition:transform .18s,background .18s}.button:hover{transform:translateY(-1px)}.primary{background:var(--green);color:white}.primary:hover{background:var(--green-dark)}.secondary{background:transparent;color:var(--ink);border-color:#c9cec8}.hero{display:grid;grid-template-columns:1.04fr .96fr;gap:40px;align-items:center;padding:78px 0 68px;min-height:520px}.eyebrow{font-size:10px;letter-spacing:.16em;text-transform:uppercase;font-weight:750;color:var(--green);display:flex;align-items:center;gap:10px}.eyebrow:before{content:'';height:1px;width:24px;background:var(--green)}h1,h2,h3,p{margin-top:0}.hero h1{font-family:var(--serif);font-weight:400;letter-spacing:-.055em;font-size:clamp(45px,5.2vw,72px);line-height:.99;max-width:650px;margin:22px 0 22px}.hero h1 em{font-weight:400;color:var(--green);font-style:normal}.lead{font-size:16px;line-height:1.8;color:var(--muted);max-width:500px}.hero-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:30px}.micro{margin-top:22px;font-size:11px;color:#81898a}.visual{position:relative;min-height:365px;background:#e8e8df;border:1px solid #d9ddd5;border-radius:14px;overflow:hidden;padding:22px;display:flex;align-items:center;justify-content:center}.visual:before{content:'';position:absolute;inset:0;background:linear-gradient(140deg,rgba(255,255,255,.7),transparent 55%),radial-gradient(circle at 75% 30%,rgba(8,118,95,.14),transparent 45%)}.architecture{position:absolute;inset:35px 22px 20px 24px;display:flex;align-items:center;justify-content:center;gap:8px;perspective:700px;opacity:.8}.pillar{height:240px;width:24%;border:1px solid rgba(32,42,44,.18);background:linear-gradient(100deg,#faf9f2,#d9ddd4 45%,#f5f4eb);transform:skewY(-7deg);box-shadow:18px 20px 40px rgba(32,42,44,.08)}.pillar:nth-child(2){height:285px;width:30%;background:linear-gradient(100deg,#cfd5cc,#faf9f2 60%,#c4cbc2)}.pillar:nth-child(3){height:210px}.receipt{position:relative;z-index:2;width:min(275px,80%);margin-left:-34%;margin-top:90px;padding:22px;background:rgba(255,254,250,.94);border:1px solid #dfe4dc;border-radius:10px;box-shadow:0 20px 50px rgba(32,42,44,.13)}.receipt-top{display:flex;align-items:center;justify-content:space-between;font-size:10px;color:var(--muted)}.check{height:29px;width:29px;border-radius:50%;display:grid;place-items:center;background:var(--mint);color:var(--green);font-weight:800}.receipt strong{display:block;font-family:var(--serif);font-size:24px;letter-spacing:-.04em;margin:17px 0 5px}.receipt small{font-size:10px;color:var(--muted)}.receipt-line{height:1px;background:var(--line);margin:18px 0 12px}.receipt-foot{display:flex;justify-content:space-between;align-items:center;font-size:10px;color:var(--green);font-weight:700}.trust{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:25px 0;gap:20px}.trust-item{display:flex;gap:13px;align-items:center}.icon{height:38px;width:38px;border:1px solid #d9ded6;background:#fbfaf5;border-radius:50%;display:grid;place-items:center;color:var(--green);font-size:17px;flex-shrink:0}.trust strong{display:block;font-size:12px;margin-bottom:5px}.trust span{font-size:10px;color:var(--muted)}.section{padding:92px 0}.section-head{display:flex;justify-content:space-between;align-items:end;gap:30px;margin-bottom:34px}.section h2{font-family:var(--serif);font-size:clamp(34px,4vw,48px);font-weight:400;letter-spacing:-.05em;line-height:1.05;margin:15px 0 0;max-width:540px}.section-intro{max-width:360px;color:var(--muted);font-size:13px;line-height:1.8;margin-bottom:2px}.feature-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.feature{padding:26px;background:var(--surface);border:1px solid var(--line);border-radius:10px;min-height:220px}.feature .icon{margin-bottom:32px}.feature h3{font-family:var(--serif);font-size:22px;font-weight:400;letter-spacing:-.03em;margin-bottom:10px}.feature p{font-size:12px;line-height:1.8;color:var(--muted);margin-bottom:0}.developer{background:#202a2c;color:#f6f4ed;border-radius:13px;padding:42px;display:grid;grid-template-columns:1fr .9fr;gap:40px;align-items:center}.developer .eyebrow{color:#8fd2bd}.developer .eyebrow:before{background:#8fd2bd}.developer h2{font-family:var(--serif);font-size:clamp(32px,4vw,46px);font-weight:400;letter-spacing:-.05em;line-height:1.05;margin:17px 0}.developer p{font-size:13px;line-height:1.8;color:#bdc8c4;max-width:440px}.code{background:#151d1e;border:1px solid #3b4948;border-radius:9px;padding:22px;font:12px/1.9 ui-monospace,SFMono-Regular,Menlo,monospace;color:#d6e2db;overflow:auto}.code .green{color:#8fd2bd}.code .dim{color:#81918c}.cta{display:flex;justify-content:space-between;align-items:center;gap:30px;padding:46px 0}.cta h2{font-family:var(--serif);font-size:36px;font-weight:400;letter-spacing:-.04em;margin:0}.footer{border-top:1px solid var(--line);padding:25px 0 34px;display:flex;justify-content:space-between;gap:20px;color:var(--muted);font-size:10px}.footer .brand{font-size:19px;color:var(--ink)}
        @media(max-width:850px){.shell{padding:0 22px}.navlinks{display:none}.hero{grid-template-columns:1fr;padding:58px 0 48px;gap:32px}.visual{min-height:330px}.trust{grid-template-columns:repeat(2,1fr)}.section{padding:65px 0}.developer{grid-template-columns:1fr;padding:30px}.feature-grid{grid-template-columns:1fr 1fr}.section-head{align-items:start;flex-direction:column}.section-intro{max-width:520px}}
        @media(max-width:520px){.shell{padding:0 17px}.nav{height:68px}.brand{font-size:22px}.navactions{gap:10px}.navactions>a:first-child{display:none}.navactions .button{padding:10px 12px}.hero h1{font-size:47px}.lead{font-size:14px}.visual{min-height:285px;padding:12px}.architecture{inset:25px 10px}.pillar{height:190px}.pillar:nth-child(2){height:225px}.pillar:nth-child(3){height:170px}.receipt{margin-left:-30%;margin-top:68px;padding:16px}.receipt strong{font-size:20px}.trust{gap:18px 12px}.trust-item{align-items:flex-start;gap:9px}.icon{width:32px;height:32px}.trust strong{font-size:11px}.trust span{font-size:9px}.feature-grid{grid-template-columns:1fr}.feature{min-height:unset}.feature .icon{margin-bottom:22px}.developer{padding:24px 18px}.code{font-size:10px;padding:16px}.cta{align-items:flex-start;flex-direction:column}.cta h2{font-size:30px}.footer{flex-direction:column}.section h2{font-size:36px}}
    </style>
</head>
<body>
<div class="shell">
    <header class="nav">
        <a class="brand" href="/" aria-label="Arcflow home"><span class="mark">A</span> arcflow</a>
        <nav class="navlinks" aria-label="Main navigation"><a href="#platform">Platform</a><a href="#how-it-works">How it works</a><a href="#developers">Developers</a></nav>
        <div class="navactions"><a href="/dashboard">Sign in</a><a class="button primary" href="/dashboard">Open dashboard <span aria-hidden="true">↗</span></a></div>
    </header>
    <main>
        <section class="hero" id="how-it-works">
            <div>
                <div class="eyebrow">Blockchain payment infrastructure</div>
                <h1>Money moves better when the <em>plumbing</em> just works.</h1>
                <p class="lead">Accept USDC on Arc with invoice, payment-detection and webhook infrastructure designed to keep your team focused on building.</p>
                <div class="hero-actions"><a class="button primary" href="/dashboard">Explore merchant dashboard <span aria-hidden="true">↗</span></a><a class="button secondary" href="#developers">For developers <span aria-hidden="true">↓</span></a></div>
                <div class="micro">Built for clear payment states, traceable transactions and dependable integrations.</div>
            </div>
            <div class="visual" aria-label="Illustration of a confirmed stablecoin payment">
                <div class="architecture" aria-hidden="true"><div class="pillar"></div><div class="pillar"></div><div class="pillar"></div></div>
                <div class="receipt"><div class="receipt-top"><span>ARCFLOW · PAYMENT EVENT</span><span class="check">✓</span></div><strong>Payment received</strong><small>USDC transfer detected on Arc</small><div class="receipt-line"></div><div class="receipt-foot"><span>Traceable on-chain</span><span>↗</span></div></div>
            </div>
        </section>
        <section class="trust" aria-label="Platform capabilities">
            <div class="trust-item"><span class="icon">◉</span><div><strong>USDC invoices</strong><span>Clear payment requests</span></div></div>
            <div class="trust-item"><span class="icon">⌁</span><div><strong>On-chain detection</strong><span>Transaction-aware tracking</span></div></div>
            <div class="trust-item"><span class="icon">◇</span><div><strong>Webhook events</strong><span>Integrate with your stack</span></div></div>
            <div class="trust-item"><span class="icon">↗</span><div><strong>Developer-first</strong><span>API-oriented infrastructure</span></div></div>
        </section>
        <section class="section" id="platform">
            <div class="section-head"><div><div class="eyebrow">One coherent workflow</div><h2>Payment operations, without the guesswork.</h2></div><p class="section-intro">From the first invoice to the on-chain evidence, Arcflow brings the important details into one understandable workflow.</p></div>
            <div class="feature-grid">
                <article class="feature"><span class="icon">▤</span><h3>Invoice lifecycle</h3><p>Create payment requests, share a dedicated payment page and follow each invoice through its current status.</p></article>
                <article class="feature"><span class="icon">⌁</span><h3>On-chain visibility</h3><p>Follow transaction evidence and confirmation progress with links to the blockchain explorer where available.</p></article>
                <article class="feature"><span class="icon">↗</span><h3>Integration-ready</h3><p>Connect payment workflows to your application through the existing API and webhook infrastructure.</p></article>
            </div>
        </section>
        <section class="developer" id="developers">
            <div><div class="eyebrow">Designed for builders</div><h2>Make stablecoin payments part of your product.</h2><p>Use Arcflow's invoice and payment APIs to connect your product to on-chain payment activity. Keep your application logic in control while payment operations stay observable.</p><a class="button" style="border-color:#6b9f91;color:#f6f4ed" href="/dashboard">View merchant workspace <span aria-hidden="true">↗</span></a></div>
            <div class="code" aria-label="Illustrative API request"><span class="dim">// Create a payment invoice</span><br><span class="green">POST</span> /api/v1/invoices<br><br>{<br>&nbsp;&nbsp;<span class="green">"amount"</span>: <span class="green">"125.00"</span>,<br>&nbsp;&nbsp;<span class="green">"currency"</span>: <span class="green">"USDC"</span><br>}<br><br><span class="dim">// Check your existing API contract</span></div>
        </section>
        <section class="cta"><div><div class="eyebrow">A clearer way to collect</div><h2>Start with a better payment workflow.</h2></div><a class="button primary" href="/dashboard">Open Arcflow <span aria-hidden="true">↗</span></a></section>
    </main>
    <footer class="footer"><a class="brand" href="/"> <span class="mark">A</span> arcflow</a><span>Blockchain payment infrastructure for modern businesses.</span><span>Built for clarity. Designed for trust.</span></footer>
</div>
</body>
</html>
